select.where:
del_flag ='0'
and INSTR(machine_code, #{machineCode,jdbcType=VARCHAR}) > 0 and machine_name like concat(concat('%', #{machineName}), '%')
and status = #{status}
order by CREATE_TIME desc
order by ${orderStr}

del_flag ='0'
and id != #{id}
and machine_code = #{machineCode}
and machine_name = #{machineName}

mapper.update:
update t_xwyy_machine_info
machine_name = #{machineName,jdbcType=VARCHAR}, quata = #{quata,jdbcType=DECIMAL}, class_shift = #{classShift,jdbcType=VARCHAR}, open_machine_class = #{openMachineClass,jdbcType=VARCHAR}, status = #{status,jdbcType=VARCHAR}, remark = #{remark,jdbcType=VARCHAR}, del_flag = #{delFlag,jdbcType=VARCHAR}, create_by = #{createBy,jdbcType=VARCHAR}, create_time = #{createTime,jdbcType=DATE}, update_by = #{updateBy,jdbcType=VARCHAR}, update_time = #{updateTime,jdbcType=DATE},
where id = #{id}

select.if:
select a.MACHINE_ID as ID,b.MACHINE_CODE,b.MACHINE_NAME
from T_XWYY_MACHINE_ROLL_MAPPING a
inner JOIN T_XWYY_MACHINE_INFO b
on a.MACHINE_ID=b.ID and b.STATUS = '0'
where a.DEL_FLAG='0'
and a.BIG_ROLL_CODE= #{machineCode,jdbcType=VARCHAR}
and a.MACHINE_ID not in (
select MACHINE_ID from T_XWYY_SPECIFY_MACHINE where DEL_FLAG='0' and JOB_TYPE='0' and
BIG_ROLL_CODE=#{machineCode,jdbcType=VARCHAR}
)

select a.ID,a.MACHINE_CODE,a.MACHINE_NAME from t_xwyy_machine_info a
where a.DEL_FLAG='0' and a.STATUS='0'
and a.ID not in (
select MACHINE_ID from T_XWYY_SPECIFY_MACHINE where DEL_FLAG='0' and JOB_TYPE='0' and
BIG_ROLL_CODE=#{machineCode,jdbcType=VARCHAR}
union
select MACHINE_ID from T_XWYY_MACHINE_ROLL_MAPPING where DEL_FLAG='0' and
BIG_ROLL_CODE=#{machineCode,jdbcType=VARCHAR}
)
